def compute(vars):
    qualifying_years = []
    if vars["v1"] < 10:
        qualifying_years.append(2019)
    if vars["v2"] < 10:
        qualifying_years.append(2018)

    return {
        "value": len(qualifying_years),
        "trace": {
            "qualifying_years": qualifying_years,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "count"
            }
        }
    }
